export type UpdateFlags = {
  /** Only update the admin UI */
  admin?: boolean;
  /** Check for updates without installing */
  check?: boolean;
  /** Only update the CLI binary */
  cli?: boolean;
  /** Force update even if already up to date */
  force?: boolean;
  /** Show the pin diff (CLI, images, plugins) and the upgrade steps; writes nothing */
  plan?: boolean;
  /** Restart services after update */
  restart?: boolean;
  /** Download a specific version (e.g. v1.2.3) */
  version?: string;
  /** Apply the image and plugin pins, rebuild, then update the CLI last (--cli=false skips the CLI) */
  yes?: boolean;
};

